    "category": "可用性管理・キャパシティ管理",
    "question": "\"ITサービスが必要とされるときに,合意した条件の下で要求された機能を果たせる状態にある能力\"について,定義し,分析し,計画し,測定し,改善する活動を行うITILの管理プロセスはどれか。",
