    "question": "\"24時間365日\"の有人オペレーションサービスを提供する。シフト勤務の条件が次のとき,オペレータは最少で何人必要か。\n\n[条件]\n(1) 1日に3シフトの交代勤務とする。\n(2) 各シフトで勤務するオペレータは2人以上とする。\n(3) 各オペレータの勤務回数は7日間当たり5回以内とする。",
