    "question": "プロジェクトの進捗管理をEVM（Earned Value Management）で行っている。コストが超過せず、納期にも遅れないと予想されるプロジェクトはどれか。ここで、それぞれのプロジェクトの開発の生産性は現在までと変わらないものとする。（下図参照）",
    "image": "data/images/PE-2014-16.png",
