    "explanation": "ARP(Address Resolution Protocol)は、同一セグメント内でIPアドレスから対応するMACアドレスを求めるためのプロトコルであるため、アが正しい。イのIPアドレスからホスト名を得る機能は逆引きDNS(PTRレコード)の機能であるため誤り。ウのMACアドレスからIPアドレスを得る機能はRARP(Reverse ARP)の機能であるため誤り。エのホスト名からIPアドレスを得る機能はDNSの正引き機能であるため誤りである。"
