    "qnum": 23,
    "category": "セキュリティ管理",
    "question": "JIS Q 27000において,\"エンティティは,それが主張するとおりのものであるという特性\"と定義されているものはどれか。",
    "choices": {
      "ア": "真正性",
      "イ": "信頼性",
      "ウ": "責任追跡性",
      "エ": "否認防止"
    },
