    "question": "ITILにおいて,良い目標値を設定するための条件として\"SMART\"がある。\"S\"はSpecific(具体的),\"M\"はMeasurable(測定可能),\"R\"はRelevant(適切),\"T\"はTime-bound(適時)の頭文字である。\"A\"は何の頭文字か。",
