    "question": "システムの信頼性を測る指標の一つに稼働品質率がある。年間の稼働品質率で評価される信頼性が最も高いシステムはどれか。ここで、稼働品質率は次の式で算出し、システムの資産規模には総運用費用を用いるものとする。\n\n稼働品質率 = 利用者に迷惑を掛けた回数 ÷ システムの資産規模\n\nシステム | 迷惑を掛けた回数(オンライン処理,回/年) | 迷惑を掛けた回数(バッチ処理,回/年) | オンラインシステムの稼働時間(千時間/年) | 総運用費用(百万円/年)\nA | 3 | 12 | 6 | 120\nB | 4 | 8 | 3 | 100\nC | 6 | 2 | 4 | 80\nD | 6 | 3 | 2 | 60",
