      "ウ": "問題管理プロセスは、既知の誤り及び問題解決策に関する最新の情報を、インシデント及びサービス要求管理プロセスに提供しなければならない。",
      "エ": "問題管理プロセスは、問題の根本原因を正すために要求される変更を、インシデント及びサービス要求管理プロセスに伝えなければならない。"
