    "question": "複数台の物理サーバで多数の仮想サーバを提供しているシステムがある。次の条件で運用する場合、物理サーバが8台停止してもリソースの消費を平均80%以内にするには、物理サーバが1台も停止していないときは最低何台必要か。ここで、各物理サーバは同一の性能と同一のリソースを有しているものとする。\n\n[条件]\n(1) ある物理サーバが停止すると、その物理サーバ内の全ての仮想サーバを、稼働中の物理サーバに、リソースの消費が均等になるように再配分する。\n(2) 物理サーバが1台も停止していないときのリソースの消費は、平均60%である。\n(3) その他の条件は考慮しない。",
