    "question": "エラープルーフ化とは、ヒューマンエラーに起因する障害を防ぐ目的で、作業方法を人間に合うように改善することであり、次の五つの原理を定義している。五つの原理のうち、ヒューマンエラーの発生を未然に防止する原理の組みはどれか。\n\n[エラープルーフ化の五つの原理]\n・異常検出:エラーに気づくようにする。\n・影響緩和:影響が致命的なものにならないようにする。\n・代替化:人が作業をしなくてもよいようにする。\n・排除:作業や注意を不要にする。\n・容易化:作業を易しくする。",
