    "explanation": "成人の虹彩パターンは加齢による経年変化がほとんどなく安定しているため、虹彩認証では認証デバイスでのパターン更新がほとんど不要であり、イが正しい。アはUSBメモリ型の認証デバイスに接続先PCのMACアドレスを組み込む必要があるとしているが、これは一般的な要件ではない。ウは静電容量方式の指紋認証がLED照明下で正常に認証できなくなる可能性が高いとしているが、静電容量方式は指の電気的な凹凸を検出する方式であり外光の影響を受けにくく、むしろ光学式の指紋認証の方が外光の影響を受けやすい。エは接触型ICカードがコイルの誘導起電力を利用しているとしているが、コイルの誘導起電力を利用するのは非接触型ICカードであり、接触型ICカードは電気接点を介して給電・通信を行う点で異なる。"
