    "question": "故障発生率が1.0×10⁻⁶回／秒である機器10,000台が稼働している。330時間経過後に、故障していない機器の台数はおよそ何台か。ここで、故障発生率は経過時間によらず一定で、故障した機器は修理しない。また、必要であれば、故障発生率をλ回／秒、稼働時間をt秒とする指数関数のグラフから値を読み取って、計算に使用してよい。（グラフは下図参照）",
