    "question": "ソフトウェアを開発するために、ローコード開発ツールを選定する。ツールを使って作成するプログラムには、ツールが提供する部品を組み合わせるだけで完成するプログラム(タイプ1プログラム)と、ソースコードを記述して作成するプログラム(タイプ2プログラム)とがある。表は、A〜Dのツールを使ってソフトウェアを開発する場合の、タイプ1プログラム及びタイプ2プログラムのそれぞれのプログラム本数及び1本当たりの所要工数の見積りである。最も少ない工数で開発できるツールはどれか。\n[ローコード開発ツールごとのプログラム本数と所要工数]\nツールA: タイプ1本数50本(0.5人日/本)、タイプ2本数5本(20人日/本)\nツールB: タイプ1本数50本(0.8人日/本)、タイプ2本数4本(20人日/本)\nツールC: タイプ1本数50本(1.0人日/本)、タイプ2本数3本(20人日/本)\nツールD: タイプ1本数50本(1.5人日/本)、タイプ2本数2本(20人日/本)",
