    "choices": {
      "ア": "10",
      "イ": "20",
      "ウ": "30",
      "エ": "40"
    },
    "answer": "エ",
    "explanation": "端末Bの回線速度は端末Aの1/10であるため伝送時間は10倍かかり、端末Aの片道伝送時間をxとすると端末AのターンアラウンドタイムはA側2x＋処理時間＝100、B側は20x＋処理時間＝820という関係が成り立つ。これを解くとx＝40ミリ秒となり、エが正解である。ア(10)・イ(20)・ウ(30)は、回線速度比(10倍)の適用を誤ったり、処理時間の扱い(連立方程式からの消去)を誤って計算したりした場合に生じ得る値であり、正しく連立方程式を解けば40ミリ秒という値には至らない。"
