    "question": "金融庁“財務報告に係る内部統制の評価及び監査に関する実施基準（令和5年）”によれば、“記録した取引に漏れ、重複がないこと”は、組織目標を達成するためのITの統制目標のうち、どれに含まれるか。",
    "choices": {
      "ア": "可用性",
      "イ": "機密性",
      "ウ": "完全性",
      "エ": "信頼性"
    },
